,"level":"all","weeks":2,"status":"open"},{"slug":"guest-contemp","position":6,"title_t":{"en":"Guest Lab 04","ko":"게스트 랩 04"},"subtitle_t":{"en":"Contemporary Lines","ko":"컨템포러리 라인"},"promise_t":{"en":"Floor, reach and suspension borrowed from contemporary.","ko":"컨템포러리에서 가져온 플로어, 뻗음, 그리고 서스펜션."},"level":"advanced","weeks":2,"status":"soon"},{"slug":"guest-groove","position":7,"title_t":{"en":"Guest Lab 05","ko":"게스트 랩 05"},"subtitle_t":{"en":"Hip-Hop Grooves","ko":"힙합 그루브"},"promise_t":{"en":"Bounce and groove that survive salsa timing.","ko":"살사 타이밍 위에서도 살아남는 바운스와 그루브."},"level":"intermediate","weeks":2,"status":"soon"},{"slug":"guest-flam","position":8,"title_t":{"en":"Guest Lab 06","ko":"게스트 랩 06"},"subtitle_t":{"en":"Flamenco Arms","ko":"플라멩코 팔"},"promise_t":{"en":"Wrists, forearms and intention above the waist.","ko":"손목과 팔뚝, 그리고 허리 위의 의도."},"level":"advanced","weeks":2,"status":"soon"}]}]'::jsonb as d),
ins_areas as (
  insert into public.areas (slug, position, name_t, blurb_t)
  select a ->> 'slug', (a ->> 'position')::int, a -> 'name_t', a -> 'blurb_t'
  from payload, jsonb_array_elements(d) a
  returning id, slug
)
insert into public.programs (area_id, slug, position, title_t, subtitle_t, promise_t, level, weeks, status, published_at)
select ia.id, p ->> 'slug', (p ->> 'position')::int, p -> 'title_t', p -> 'subtitle_t', p -> 'promise_t',
       (p ->> 'level')::level_key, (p ->> 'weeks')::int, (p ->> 'status')::publish_status,
       case when p ->> 'status' = 'open' then now() end
from payload, jsonb_array_elements(d) a
join ins_areas ia on ia.slug = a ->> 'slug'
cross join lateral jsonb_array_elements(a -> 'programs') p;

-- 2. sessions of improvisation-01
insert into public.sessions (program_id, position, title_t, outcome_t, focus_t, levels, status)
select (select id from public.programs where slug = 'improvisation-01'),
       (s ->> 'position')::int, s -> 'title_t', s -> 'outcome_t', s -> 'focus_t',
       (select array_agg(value::text::level_key) from jsonb_array_elements_text(s -> 'levels') value),
       'open'
from jsonb_array_elements('[{"position":1,"title_t":{"en":"One Step, Many Possibilities","ko":"하나의 스텝, 여러 가능성"},"outcome_t":{"en":"Transform a Suzie Q through direction and size.","ko":"수지큐를 방향과 크기로 변형합니다."},"focus_t":{"en":"direction and size","ko":"방향과 크기"},"levels":["all","beginner"]},{"position":2,"title_t":{"en":"Change the Rhythm","ko":"리듬 바꾸기"},"outcome_t":{"en":"Use holds and syncopation without adding vocabulary.","ko":"동작을 늘리지 않고 홀드와 싱코페이션을 사용합니다."},"focus_t":{"en":"rhythm","ko":"리듬"},"levels":["beginner","intermediate"]},{"position":3,"title_t":{"en":"Connect Without Planning","ko":"계획 없이 연결하기"},"outcome_t":{"en":"Move among basic, Suzie Q and crossover.","ko":"기본, 수지큐, 크로스오버 사이를 오갑니다."},"focus_t":{"en":"transitions","ko":"연결"},"levels":["all","intermediate"]},{"position":4,"title_t":{"en":"Repeat Without Looking Repetitive","ko":"반복하되 단조롭지 않게"},"outcome_t":{"en":"Use repetition with changing energy or direction.","ko":"에너지나 방향을 바꾸며 반복합니다."},"focus_t":{"en":"energy","ko":"에너지"},"levels":["all","intermediate"]},{"position":5,"title_t":{"en":"Change Direction","ko":"방향 바꾸기"},"outcome_t":{"en":"Travel intentionally through the space.","ko":"공간 안에서 의도를 가지고 이동합니다."},"focus_t":{"en":"travel","ko":"이동"},"levels":["all","beginner"]},{"position":6,"title_t":{"en":"Create Eight Counts","ko":"8카운트 만들기"},"outcome_t":{"en":"Make and repeat a short phrase that is yours.","ko":"나만의 짧은 프레이즈를 만들고 반복합니다."},"focus_t":{"en":"phrasing","ko":"프레이즈"},"levels":["intermediate","advanced"]},{"position":7,"title_t":{"en":"React to Rhythm","ko":"리듬에 반응하기"},"outcome_t":{"en":"Recognise and answer a simple musical cue.","ko":"간단한 음악적 신호를 알아채고 응답합니다."},"focus_t":{"en":"musical cues","ko":"음악 신호"},"levels":["intermediate","advanced"]},{"position":8,"title_t":{"en":"Use Pauses","ko":"멈춤 사용하기"},"outcome_t":{"en":"Hold with intention, then restart confidently.","ko":"의도를 가지고 멈추고, 자신 있게 다시 시작합니다."},"focus_t":{"en":"pauses","ko":"멈춤"},"levels":["all","advanced"]},{"position":9,"title_t":{"en":"Sixty-Second Freestyle","ko":"60초 프리스타일"},"outcome_t":{"en":"Dance on your own with the prompts falling away.","ko":"안내가 줄어드는 가운데 스스로 춤춥니다."},"focus_t":{"en":"free choice","ko":"자유 선택"},"levels":["advanced","pro"]}]'::jsonb) s;

-- 3. videos: an ordered list per session, expanded from the step templates
with steps as (
  select s ->> 'key' as key, s -> 'title_t' as title_t, s -> 'description_t' as description_t,
         (s ->> 'duration_ms')::int as duration_ms
  from jsonb_array_elements('[{"key":"watch","title_t":{"en":"See where this goes","ko":"도착점 보기"},"description_t":{"en":"The whole thing danced to music, before any explanation.","ko":"설명에 앞서, 음악에 맞춘 완성된 모습을 봅니다."},"duration_ms":20000},{"key":"understand","title_t":{"en":"The idea and the cues","ko":"아이디어와 큐"},"description_t":{"en":"One idea, and no more than three cues that change how it feels.","ko":"하나의 아이디어와, 감각을 바꾸는 최대 세 가지 큐."},"duration_ms":240000},{"key":"train","title_t":{"en":"Build the base","ko":"기본 쌓기"},"description_t":{"en":"Build the base slowly, with counts and the styling stripped out.","ko":"스타일링을 걷어내고 카운트로 기본을 천천히 쌓습니다."},"duration_ms":180000},{"key":"drill","title_t":{"en":"Repeat it to music","ko":"음악에 맞춰 반복"},"description_t":{"en":"Follow view. Repeat to music until it stops needing your attention.","ko":"후면 뷰. 신경 쓰지 않아도 나올 때까지 음악에 맞춰 반복합니다."},"duration_ms":240000},{"key":"transform","title_t":{"en":"Change one thing","ko":"하나만 바꾸기"},"description_t":{"en":"Change one variable and compare the result against the base.","ko":"한 가지 변수를 바꾸고 기본형과 비교합니다."},"duration_ms":220000},{"key":"improvise","title_t":{"en":"Your turn","ko":"나의 차례"},"description_t":{"en":"One rule, a timer, and no demonstration to copy.","ko":"규칙 하나와 타이머, 따라 할 시범은 없습니다."},"duration_ms":180000}]'::jsonb) s
),
plan as (
  select (p ->> 'session')::int as session_no,
         step_key::text as step_key,
         ord::int as position
  from jsonb_array_elements('[{"session":1,"steps":["watch","understand","train","drill","transform","improvise"]},{"session":2,"steps":["watch","understand","train","drill","transform","improvise"]},{"session":3,"steps":["watch","understand","train","drill","transform","improvise"]},{"session":4,"steps":["watch","understand","train","drill","transform","improvise"]},{"session":5,"steps":["watch","understand","train","drill","transform","improvise"]},{"session":6,"steps":["watch","understand","train","train","drill","transform","improvise"]},{"session":7,"steps":["watch","understand","train","drill","transform","improvise"]},{"session":8,"steps":["watch","understand","train","drill","transform","improvise"]},{"session":9,"steps":["watch","train","drill","transform","improvise","improvise"]}]'::jsonb) p
  cross join lateral jsonb_array_elements_text(p -> 'steps') with ordinality as t(step_key, ord)
),
numbered as (
  select *,
         count(*) over (partition by session_no, step_key) as of_step,
         row_number() over (partition by session_no, step_key order by position) as nth
  from plan
)
insert into public.videos (session_id, step, position, title_t, description_t, duration_ms, mirror_default, status)
select ses.id,
       n.step_key::method_step,
       n.position,
       case when n.of_step > 1
            then jsonb_build_object('en', (st.title_t ->> 'en') || ' ' || n.nth,
                                    'ko', (st.title_t ->> 'ko') || ' ' || n.nth)
            else st.title_t end,
       st.description_t,
       st.duration_ms,
       n.step_key = 'train',   -- train is filmed facing you, so it opens mirrored
       'uploading'             -- no footage exists yet; the back office moves these to ready
from numbered n
join steps st on st.key = n.step_key
join public.sessions ses
  on ses.position = n.session_no
 and ses.program_id = (select id from public.programs where slug = 'improvisation-01');
